 $db->beginTransaction();$sql="SELECT d.id documento_id,d.tipo,a.id acuerdo_id,COALESCE(a.fecha_acuerdo,CURDATE()) fecha_acuerdo,COALESCE(a.tipo_acuerdo,'CANCELACION') tipo_acuerdo,COALESCE(a.saldo_negociado,o.saldo) deuda_total,COALESCE(a.monto_acordado,o.saldo) monto_acordado,COALESCE(a.monto_inicial,0) monto_inicial,c.nombre_completo,c.numero_documento dni,c.direccion,c.distrito,c.departamento,a.telefono_documento telefono,a.correo_documento correo,o.numero_operacion,o.producto FROM documentos d LEFT JOIN acuerdos a ON a.id=d.acuerdo_id JOIN clientes c ON c.id=COALESCE(d.cliente_id,a.cliente_id) JOIN operaciones o ON o.id=COALESCE(d.operacion_id,a.operacion_id) WHERE(d.estado='PENDIENTE' OR(d.estado='GENERANDO' AND d.updated_at<DATE_SUB(NOW(),INTERVAL 15 MINUTE)))AND(d.acuerdo_id IS NOT NULL OR d.solicitado_por IS NOT NULL) ORDER BY CASE WHEN d.solicitado_por IS NOT NULL THEN 0 ELSE 1 END,d.updated_at,d.id LIMIT 1 FOR UPDATE";$row=$db->query($sql)->fetch();if(!$row){$db->commit();exit(json_encode(['ok'=>true,'job'=>null]));}$db->prepare("UPDATE documentos SET estado='GENERANDO' WHERE id=?")->execute([$row['documento_id']]);$row['cuotas']=[];if($row['acuerdo_id']){$q=$db->prepare('SELECT numero_cuota,fecha_vencimiento fecha,monto FROM cuotas WHERE acuerdo_id=? ORDER BY numero_cuota');$q->execute([$row['acuerdo_id']]);$row['cuotas']=$q->fetchAll();}$db->commit();exit(json_encode(['ok'=>true,'job'=>$row],JSON_UNESCAPED_UNICODE));
